func TestVerifyDownloadFailures(t *testing.T) {
	tmpDir := t.TempDir()
	BundlePath = filepath.Join(tmpDir, "Ollama.app")
	UpdateStageDir = filepath.Join(tmpDir, "staging")
	bundle := filepath.Join(UpdateStageDir, "foo", "ollama-darwin.zip")
