app.updater.updater_darwin_test.zipCreat.source_code:
func zipCreationHelper(filename string, files []testPayload) error {
	fd, err := os.Create(filename)
	if err != nil {
		return err
	}

	w := zip.NewWriter(fd)
	for _, file := range files {
		fh := &zip.FileHeader{
			Name:  file.Name,
			Flags: 0,
		}
		if file.Mode != 0 {
			fh.SetMode(file.Mode)
		}
		f, err := w.CreateHeader(fh)
		if err != nil {
			return err
		}
		_, err = f.Write(file.Body)
		if err != nil {
			return err
		}
	}
	return w.Close()
}

