func NewTray(app AppCallbacks) (TrayCallbacks, error) {
	updateIcon, err := assets.GetIcon(UpdateIconName)
	if err != nil {
		return nil, fmt.Errorf("failed to load icon %s: %w", UpdateIconName, err)
	}
	icon, err := assets.GetIcon(IconName)
	if err != nil {
