func (h *Hermes) CurrentModel() string {
	backend, err := h.configBackend()
	if err != nil {
		return ""
	}
	data, err := backend.read()
	if err != nil {
		return ""
	}

	cfg := map[string]any{}
	if yaml.Unmarshal(data, &cfg) != nil {
		return ""
	}
	return hermesManagedCurrentModel(cfg, hermesBaseURL())
}

