	if hermesGOOS == "windows" {
		if _, err := hermesLookPath("hermes"); err == nil {
			path, err := hermesEnvPath()
			if err != nil {
				return nil, err
			}
			return os.ReadFile(path)
		}
		if h.wslAvailable() {
			home, err := h.wslHome()
			if err != nil {
				return nil, err
			}
			return h.readWSLFile(pathpkg.Join(home, ".hermes", ".env"))
		}
	}

	path, err := hermesEnvPath()
	if err != nil {
		return nil, err
	}
	return os.ReadFile(path)
}

