func TestVersionLessThan(t *testing.T) {
	tests := []struct {
		a, b string
		want bool
	}{
		{"0.1.7", "0.2.1", true},
		{"0.2.0", "0.2.1", true},
		{"0.2.1", "0.2.1", false},
		{"0.2.2", "0.2.1", false},
		{"1.0.0", "0.2.1", false},
		{"0.2.1", "1.0.0", true},
		{"v0.1.7", "0.2.1", true},
		{"0.2.1", "v0.2.1", false},
	}
	for _, tt := range tests {
		t.Run(tt.a+"_vs_"+tt.b, func(t *testing.T) {
			if got := versionLessThan(tt.a, tt.b); got != tt.want {
				t.Errorf("versionLessThan(%q, %q) = %v, want %v", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

