func ensureNpmInstalled() error {
	if _, err := exec.LookPath("npm"); err != nil {
		return fmt.Errorf("npm (Node.js) is required to launch pi

Install it first:
  https://nodejs.org/

Then re-run:
  ollama launch pi")
	}
