cmd.tui.confirm.confirmModel.Update.source_code:
func (m confirmModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		wasSet := m.width > 0
		m.width = msg.Width
		if wasSet {
			return m, tea.EnterAltScreen
		}
		return m, nil

	case tea.KeyMsg:
		switch msg.String() {
		case "ctrl+c", "esc":
			m.cancelled = true
			return m, tea.Quit
		case "enter":
			m.confirmed = true
			return m, tea.Quit
		case "left":
			m.yes = true
		case "right":
			m.yes = false
		}
	}

	return m, nil
}

cmd.tui.confirm.confirmModel.View.source_code:
func (m confirmModel) View() string {
	if m.confirmed || m.cancelled {
		return ""
	}

	var yesBtn, noBtn string
	yesLabel := m.yesLabel
	if yesLabel == "" {
		yesLabel = "Yes"
	}
	noLabel := m.noLabel
	if noLabel == "" {
		noLabel = "No"
	}
	if m.yes {
		yesBtn = confirmActiveStyle.Render(" " + yesLabel + " ")
		noBtn = confirmInactiveStyle.Render(" " + noLabel + " ")
	} else {
		yesBtn = confirmInactiveStyle.Render(" " + yesLabel + " ")
		noBtn = confirmActiveStyle.Render(" " + noLabel + " ")
	}

	s := selectorTitleStyle.Render(m.prompt) + "\n\n"
	s += "  " + yesBtn + "  " + noBtn + "\n\n"
	s += selectorHelpStyle.Render("←/→ navigate • enter confirm • esc cancel")

	if m.width > 0 {
		return lipgloss.NewStyle().MaxWidth(m.width).Render(s)
	}
	return s
}

