cmd.tui.confirm.RunConfirmWithOptions.source_code:
func RunConfirmWithOptions(prompt string, options ConfirmOptions) (bool, error) {
	yesLabel := options.YesLabel
	if yesLabel == "" {
		yesLabel = "Yes"
	}
	noLabel := options.NoLabel
	if noLabel == "" {
		noLabel = "No"
	}

	m := confirmModel{
		prompt:   prompt,
		yesLabel: yesLabel,
		noLabel:  noLabel,
		yes:      true, // default to yes
	}

	p := tea.NewProgram(m)
	finalModel, err := p.Run()
	if err != nil {
		return false, fmt.Errorf("error running confirm: %w", err)
	}

	fm := finalModel.(confirmModel)
	if fm.cancelled {
		return false, ErrCancelled
	}

	return fm.yes, nil
}

