convert.json_compat.sanitizeNonFiniteJSO.source_code:
func sanitizeNonFiniteJSON(in []byte) []byte {
	if len(in) == 0 {
		return in
	}

	out := make([]byte, 0, len(in))
	inString := false
	escape := false

	for i := 0; i < len(in); {
		c := in[i]

		if inString {
			out = append(out, c)
			if escape {
				escape = false
			} else if c == '\\' {
				escape = true
			} else if c == '"' {
				inString = false
			}
			i++
			continue
		}

		if c == '"' {
			inString = true
			out = append(out, c)
			i++
			continue
		}

		if hasToken(in, i, "-Infinity") {
			out = append(out, '0')
			i += len("-Infinity")
			continue
		}

		if hasToken(in, i, "Infinity") {
			out = append(out, '0')
			i += len("Infinity")
			continue
		}

		if hasToken(in, i, "NaN") {
			out = append(out, '0')
			i += len("NaN")
			continue
		}

		out = append(out, c)
		i++
	}

	return out
}

convert.json_compat.hasToken.source_code:
func hasToken(in []byte, at int, tok string) bool {
	end := at + len(tok)
	if at < 0 || end > len(in) {
		return false
	}
	if string(in[at:end]) != tok {
		return false
	}
	if at > 0 && !isJSONValuePrefixBoundary(in[at-1]) {
		return false
	}
	if end < len(in) && !isJSONValueSuffixBoundary(in[end]) {
		return false
	}
	return true
}

convert.json_compat.isJSONWhitespace.source_code:
func isJSONWhitespace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r'
}

convert.json_compat.isJSONValuePrefixBou.source_code:
func isJSONValuePrefixBoundary(b byte) bool {
	return isJSONWhitespace(b) || b == ':' || b == ',' || b == '['
}

convert.json_compat.isJSONValueSuffixBou.source_code:
func isJSONValueSuffixBoundary(b byte) bool {
	return isJSONWhitespace(b) || b == ',' || b == ']' || b == '}'
}

