func (st safetensor) Kind() uint32 {
	kind := st.tensorBase.Kind()
	if st.dtype == "BF16" &&
		!strings.HasPrefix(st.name, "v.") &&
		!strings.HasPrefix(st.name, "s.") &&
		!strings.HasPrefix(st.name, "mm.") &&
		!strings.Contains(st.name, "ffn_gate_inp_shexp.weight") &&
		kind != tensorKindFP32 {
		kind = tensorKindBF16
	}

	return kind
}

