func LogDetails(devices []ml.DeviceInfo) {
	sort.Sort(sort.Reverse(ml.ByFreeMemory(devices))) // Report devices in order of scheduling preference
	for _, dev := range devices {
		var libs []string
		for _, dir := range dev.LibraryPath {
			if strings.Contains(dir, filepath.Join("lib", "ollama")) {
				libs = append(libs, filepath.Base(dir))
			}
		}
		typeStr := "discrete"
		if dev.Integrated {
			typeStr = "iGPU"
		}
		slog.Info("inference compute",
			"id", dev.ID,
			"filter_id", dev.FilterID,
			"library", dev.Library,
			"compute", dev.Compute(),
			"name", dev.Name,
			"description", dev.Description,
			"libdirs", strings.Join(libs, ","),
			"driver", dev.Driver(),
			"pci_id", dev.PCIID,
			"type", typeStr,
			"total", format.HumanBytes2(dev.TotalMemory),
			"available", format.HumanBytes2(dev.FreeMemory),
		)
	}
	// CPU inference
	if len(devices) == 0 {
		dev, _ := GetCPUMem()
		slog.Info("inference compute",
			"id", "cpu",
			"library", "cpu",
			"compute", "",
			"name", "cpu",
			"description", "cpu",
			"libdirs", "ollama",
			"driver", "",
			"pci_id", "",
			"type", "",
			"total", format.HumanBytes2(dev.TotalMemory),
			"available", format.HumanBytes2(dev.FreeMemory),
		)
	}
}

docs.tools.extract-examples.main.main.source_code:
func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "Usage: go run extract-examples.go <mdx-file>")
		os.Exit(1)
	}

	mdxFile := os.Args[1]

	f, err := os.Open(mdxFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()

	// Create temp directory
	tempDir, err := os.MkdirTemp("", "mdx-examples-*")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error creating temp dir: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Extracting code examples to: %s\n\n", tempDir)

	// Patterns
	codeBlockStart := regexp.MustCompile("^```([a-zA-Z0-9_-]+)\\s+([^\\s]+)$")
	codeGroupStart := regexp.MustCompile("^<CodeGroup")
	codeGroupEnd := regexp.MustCompile("^</CodeGroup>")

	scanner := bufio.NewScanner(f)
	inCodeBlock := false
	inCodeGroup := false
	var currentFile string
	var content strings.Builder
	count := 0
	codeGroupNum := 0

	for scanner.Scan() {
		line := scanner.Text()

		// Track CodeGroup boundaries
		if codeGroupStart.MatchString(line) {
			inCodeGroup = true
			codeGroupNum++
			continue
		}
		if codeGroupEnd.MatchString(line) {
			inCodeGroup = false
			continue
		}

		if inCodeBlock {
			if line == "```" {
				// End of code block - write file
				if currentFile != "" {
					outPath := filepath.Join(tempDir, currentFile)
					if err := os.WriteFile(outPath, []byte(content.String()), 0o644); err != nil {
						fmt.Fprintf(os.Stderr, "Error writing %s: %v\n", currentFile, err)
					} else {
						fmt.Printf("  - %s\n", currentFile)
						count++
					}
				}
				inCodeBlock = false
				currentFile = ""
				content.Reset()
			} else {
				content.WriteString(line)
				content.WriteString("\n")
			}
		} else {
			if matches := codeBlockStart.FindStringSubmatch(line); matches != nil {
				inCodeBlock = true
				filename := matches[2]
				// Prefix with CodeGroup number if inside a CodeGroup
				if inCodeGroup {
					currentFile = fmt.Sprintf("%02d_%s", codeGroupNum, filename)
				} else {
					currentFile = filename
				}
				content.Reset()
			}
		}
	}

	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "Error reading file: %v\n", err)
		os.Exit(1)
	}

	// Write package.json for JavaScript dependencies
	packageJSON := `{
  "name": "mdx-examples",
  "type": "module",
  "dependencies": {
    "openai": "^4",
    "ollama": "^0.5"
  }
}
`
	if err := os.WriteFile(filepath.Join(tempDir, "package.json"), []byte(packageJSON), 0o644); err != nil {
		fmt.Fprintf(os.Stderr, "Error writing package.json: %v\n", err)
	}

	// Write pyproject.toml for Python dependencies
	pyprojectTOML := `[project]
name = "mdx-examples"
version = "0.0.0"
dependencies = [
    "openai",
    "ollama",
]
`
	if err := os.WriteFile(filepath.Join(tempDir, "pyproject.toml"), []byte(pyprojectTOML), 0o644); err != nil {
		fmt.Fprintf(os.Stderr, "Error writing pyproject.toml: %v\n", err)
	}

	fmt.Printf("\n")
	fmt.Printf("Extracted %d file(s) to %s\n", count, tempDir)
	fmt.Printf("\n")
	fmt.Printf("To run examples:\n")
	fmt.Printf("\n")
