func TestHumanBytes(t *testing.T) {
	type testCase struct {
		input    int64
		expected string
	}

	tests := []testCase{
		// Test bytes (B)
		{0, "0 B"},
		{1, "1 B"},
		{999, "999 B"},

		// Test kilobytes (KB)
		{1000, "1 KB"},
		{1500, "1.5 KB"},
		{999999, "999 KB"},

		// Test megabytes (MB)
		{1000000, "1 MB"},
		{1500000, "1.5 MB"},
		{999999999, "999 MB"},

		// Test gigabytes (GB)
		{1000000000, "1 GB"},
		{1500000000, "1.5 GB"},
		{999999999999, "999 GB"},

		// Test terabytes (TB)
		{1000000000000, "1 TB"},
		{1500000000000, "1.5 TB"},
		{1999999999999, "2.0 TB"},

		// Test fractional values
		{1234, "1.2 KB"},
		{1234567, "1.2 MB"},
		{1234567890, "1.2 GB"},
	}

	for _, tc := range tests {
		t.Run(tc.expected, func(t *testing.T) {
			result := HumanBytes(tc.input)
