	}

	response := api.ChatResponse{
		Model: "test-model",
		Message: api.Message{
			Thinking: "reasoning",
			ToolCalls: []api.ToolCall{
				{
					ID: "call_234",
					Function: api.ToolCallFunction{
						Index: 0,
						Name:  "get_weather",
						Arguments: testArgs(map[string]any{
							"location": "Portland",
						}),
					},
				},
			},
		},
		Done: false,
	}

	data, err := json.Marshal(response)
