model.models.bert.embed.New.source_code:
func New(c fs.Config) (model.Model, error) {
	vocab := &tokenizer.Vocabulary{
		Values: c.Strings("tokenizer.ggml.tokens"),
		Scores: c.Floats("tokenizer.ggml.scores"),
		Types:  c.Ints("tokenizer.ggml.token_type"),
		AddBOS: c.Bool("tokenizer.ggml.add_bos_token", true),
		BOS: []int32{
			int32(cmp.Or(
				c.Uint("tokenizer.ggml.cls_token_id"),
				c.Uint("tokenizer.ggml.bos_token_id"),
			)),
		},
		AddEOS: c.Bool("tokenizer.ggml.add_eos_token", true),
		EOS: []int32{
			int32(cmp.Or(
				c.Uint("tokenizer.ggml.separator_token_id"),
				//nolint:misspell
				// NOTE: "seperator_token_id" is a typo in model metadata but we need to
				// support it for compatibility.
				c.Uint("tokenizer.ggml.seperator_token_id"),
				c.Uint("tokenizer.ggml.eos_token_id"),
			)),
		},
	}

	var t tokenizer.Tokenizer
	switch c.String("tokenizer.ggml.model", "bert") {
	case "bert":
		t = tokenizer.NewWordPiece(vocab, true)
	default:
		return nil, model.ErrUnsupportedTokenizer
	}

	return &Model{
		Tokenizer: t,
		Layers:    make([]EncoderLayer, c.Uint("block_count")),
		Options: Options{
			hiddenSize:  int(c.Uint("embedding_length")),
			numHeads:    int(c.Uint("attention.head_count")),
			numKVHeads:  int(c.Uint("attention.head_count_kv")),
			eps:         c.Float("attention.layer_norm_epsilon"),
			poolingType: pooling.Type(c.Uint("pooling_type")),
			normalize:   c.Bool("normalize_embeddings", true),
		},
	}, nil
}

