func (l *AudioClippableLinear) loadClamps() {
	if l.clampsLoaded {
		return
	}
	l.clampsLoaded = true
	if l.InputMin != nil {
		vals := l.InputMin.BackendGet()
		if len(vals) > 0 {
			l.inMin = vals[0]
		}
	}
	if l.InputMax != nil {
		vals := l.InputMax.BackendGet()
		if len(vals) > 0 {
			l.inMax = vals[0]
		}
	}
	if l.OutputMin != nil {
		vals := l.OutputMin.BackendGet()
		if len(vals) > 0 {
			l.outMin = vals[0]
		}
	}
	if l.OutputMax != nil {
		vals := l.OutputMax.BackendGet()
		if len(vals) > 0 {
			l.outMax = vals[0]
		}
	}
}

func (l *AudioClippableLinear) Forward(ctx ml.Context, x ml.Tensor) ml.Tensor {
	l.loadClamps()
	if l.inMax != 0 {
		x = x.Clamp(ctx, l.inMin, l.inMax)
	}
	out := l.Weight.Mulmat(ctx, x)
	if l.Bias != nil {
		out = out.Add(ctx, l.Bias)
	}
	if l.outMax != 0 {
		out = out.Clamp(ctx, l.outMin, l.outMax)
	}
	return out
}

model.models.gemma4.model_audio.AudioFC.source_code:
type AudioFC struct {
	Weight ml.Tensor `gguf:"weight"`
