<arg_value>value5</arg_value>`,
			wantToolCall: api.ToolCall{
				Function: api.ToolCallFunction{
					Name:      "test-function",
					Arguments: args(`{"fifth": "value5", "first": "value1", "fourth": "value4", "second": "value2", "third": "value3"}`),
				},
