func TestLFM2Parser_parseToolCallContent(t *testing.T) {
	tests := []struct {
		name        string
		content     string
		expected    api.ToolCall
		expectError bool
	}{
		{
			name:    "python_style_single_call",
			content: `get_weather(location="Paris")`,
			expected: api.ToolCall{
				Function: api.ToolCallFunction{
					Name: "get_weather",
					Arguments: testArgs(map[string]any{
						"location": "Paris",
					}),
				},
			},
		},
		{
			name:    "python_style_with_brackets",
			content: `[get_weather(location="Paris")]`,
			expected: api.ToolCall{
				Function: api.ToolCallFunction{
					Name: "get_weather",
					Arguments: testArgs(map[string]any{
						"location": "Paris",
					}),
				},
			},
		},
		{
			name:    "python_style_complex_arguments",
			content: `process(items=['a', 'b'], config={'enabled': True})`,
			expected: api.ToolCall{
				Function: api.ToolCallFunction{
					Name: "process",
					Arguments: testArgs(map[string]any{
						"items":  []any{"a", "b"},
						"config": map[string]any{"enabled": true},
					}),
				},
			},
		},
		{
			name:    "python_style_empty_arguments",
			content: `ping()`,
			expected: api.ToolCall{
				Function: api.ToolCallFunction{
					Name:      "ping",
					Arguments: api.NewToolCallFunctionArguments(),
				},
			},
		},
		{
			name:        "missing_parenthesis",
			content:     `get_weather location="Paris")`,
			expectError: true,
		},
		{
			name:        "invalid_argument_format",
			content:     `bash(command)`,
			expectError: true,
		},
	}

	parser := &LFM2Parser{}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result, err := parser.parseToolCallContent(tt.content)

			if tt.expectError {
				if err == nil {
					t.Error("Expected error but got none")
				}
				return
			}

			if err != nil {
				t.Fatalf("Unexpected error: %v", err)
			}

			if diff := cmp.Diff(tt.expected, result, argsComparer); diff != "" {
				t.Errorf("parseToolCallContent() mismatch (-want +got):\n%s", diff)
			}
		})
	}
}

func TestLFM2Parser_parseToolCallsContent(t *testing.T) {
