func (i *Instance) SetRawModeOn() error {
	if i.Terminal.rawmode {
		return nil
	}
	fd := os.Stdin.Fd()
	termios, err := SetRawMode(fd)
	if err != nil {
		return err
	}
	i.Terminal.rawmode = true
	i.Terminal.termios = termios
	return nil
}

readline.readline.Instance.SetRawModeOff.source_code:
func (i *Instance) SetRawModeOff() {
	if !i.Terminal.rawmode {
		return
	}
	fd := os.Stdin.Fd()
	//nolint:errcheck
	UnsetRawMode(fd, i.Terminal.termios)
	i.Terminal.rawmode = false
}

readline.readline.Instance.ReadRaw.source_code:
func (i *Instance) ReadRaw() (rune, error) {
	if !i.Terminal.rawmode {
		fd := os.Stdin.Fd()
		termios, err := SetRawMode(fd)
		if err != nil {
			return 0, err
		}
		defer func() {
			//nolint:errcheck
			UnsetRawMode(fd, termios)
		}()
	}
	return i.Terminal.Read()
}

