type trackingReader struct {
	r      io.Reader
	update func(n int64, err error) // err is always nil
}

func (r *trackingReader) Read(p []byte) (n int, err error) {
	n, err = r.r.Read(p)
	r.update(int64(n), nil)
	return
}

