type Ticket struct {
	ahead chan struct{} // ticket ahead of this one
	ch    chan struct{}
}

func (t *Ticket) Ready() chan struct{} {
	return cmp.Or(t.ahead, closedChan)
}

func (t *Ticket) Done() {
	if t.ch != nil {
		close(t.ch)
	}
	t.ch = nil
}

