type Group struct {
	wg sync.WaitGroup
	n  atomic.Int64
}

func (g *Group) Go(f func()) {
	g.wg.Add(1)
	go func() {
		g.n.Add(1) // Now we are running
		defer func() {
			g.wg.Done()
			g.n.Add(-1) // Now we are done
		}()
		f()
	}()
}

