	withCopilot := makeRequest("GitHubCopilotChat/0.41.1")
	if withCopilot.ModelInfo["general.basename"] != "show-model" {
		t.Fatalf("expected general.basename to be %q, got %v", "show-model", withCopilot.ModelInfo["general.basename"])
