			`,
			wantOpeningTag: "<think>",
			wantClosingTag: "</think>",
		},
	}
	for _, c := range cases {
		tmpl := template.Must(template.New("test").Parse(c.tmplString))
		openingTag, closingTag := InferTags(tmpl)
		if openingTag != c.wantOpeningTag || closingTag != c.wantClosingTag {
