x.create.qwen35.qwen35TransposeConv1D.source_code:
func qwen35TransposeConv1D(values []float32, shape []int32) ([]float32, []int32) {
	if len(shape) != 3 {
		return values, shape
	}

	d0, d1, d2 := int(shape[0]), int(shape[1]), int(shape[2])
	out := make([]float32, len(values))
	for i := range d0 {
		for j := range d1 {
			for k := range d2 {
				inIdx := (i*d1+j)*d2 + k
				outIdx := (i*d2+k)*d1 + j
				out[outIdx] = values[inIdx]
			}
		}
	}

	return out, []int32{shape[0], shape[2], shape[1]}
}

x.create.qwen35.qwen35SplitAxis1Raw.source_code:
func qwen35SplitAxis1Raw(raw []byte, dtype string, shape []int32) ([]byte, []byte, []int32, error) {
	if len(shape) != 3 {
		return nil, nil, nil, fmt.Errorf("expected 3D tensor, got shape %v", shape)
	}
	if shape[1]%2 != 0 {
		return nil, nil, nil, fmt.Errorf("axis 1 dim %d is not even", shape[1])
	}

	elemSize, err := DTypeSize(dtype)
	if err != nil {
		return nil, nil, nil, err
	}

	d0, d1, d2 := int(shape[0]), int(shape[1]), int(shape[2])
	perExpertBytes := d1 * d2 * elemSize
	if len(raw) != d0*perExpertBytes {
		return nil, nil, nil, fmt.Errorf("raw byte length %d does not match shape %v and dtype %s", len(raw), shape, dtype)
	}

	halfD1 := d1 / 2
	halfExpertBytes := halfD1 * d2 * elemSize
	gateRaw := make([]byte, d0*halfExpertBytes)
	upRaw := make([]byte, d0*halfExpertBytes)
	for e := range d0 {
		src := e * perExpertBytes
		dst := e * halfExpertBytes
		copy(gateRaw[dst:dst+halfExpertBytes], raw[src:src+halfExpertBytes])
		copy(upRaw[dst:dst+halfExpertBytes], raw[src+halfExpertBytes:src+perExpertBytes])
	}

	return gateRaw, upRaw, []int32{shape[0], int32(halfD1), shape[2]}, nil
}

x.imagegen.cache.cache.KVCache.source_code:
type KVCache struct {
	keys, values *mlx.Array
	offset       int
	step         int
}

x.imagegen.cache.cache.KVCache.Update.source_code:
func (c *KVCache) Update(k, v *mlx.Array, seqLen int) (*mlx.Array, *mlx.Array) {
	prev := c.offset
	shape := k.Shape()
	B, H, Dk := shape[0], shape[1], shape[3]
	Dv := v.Shape()[3]

	// Grow buffer if needed
	if c.keys == nil || (prev+seqLen) > int(c.keys.Shape()[2]) {
		nSteps := (c.step + seqLen - 1) / c.step
		newK := mlx.Zeros([]int32{B, H, int32(nSteps * c.step), Dk}, k.Dtype())
		newV := mlx.Zeros([]int32{B, H, int32(nSteps * c.step), Dv}, v.Dtype())

		if c.keys != nil {
			if prev%c.step != 0 {
				c.keys = mlx.Slice(c.keys, []int32{0, 0, 0, 0}, []int32{B, H, int32(prev), Dk})
				c.values = mlx.Slice(c.values, []int32{0, 0, 0, 0}, []int32{B, H, int32(prev), Dv})
			}
			c.keys = mlx.Concatenate([]*mlx.Array{c.keys, newK}, 2)
			c.values = mlx.Concatenate([]*mlx.Array{c.values, newV}, 2)
		} else {
			c.keys, c.values = newK, newV
		}
	}

	c.offset += seqLen
	c.keys = mlx.SliceUpdateInplace(c.keys, k, []int32{0, 0, int32(prev), 0}, []int32{B, H, int32(c.offset), Dk})
	c.values = mlx.SliceUpdateInplace(c.values, v, []int32{0, 0, int32(prev), 0}, []int32{B, H, int32(c.offset), Dv})

	return mlx.Slice(c.keys, []int32{0, 0, 0, 0}, []int32{B, H, int32(c.offset), Dk}),
		mlx.Slice(c.values, []int32{0, 0, 0, 0}, []int32{B, H, int32(c.offset), Dv})
}

