x.imagegen.image.flattenAlpha.source_code:
func flattenAlpha(img image.Image) image.Image {
	if _, ok := img.(*image.RGBA); !ok {
		if _, ok := img.(*image.NRGBA); !ok {
			// No alpha channel, return as-is
			return img
		}
	}

	bounds := img.Bounds()
	dst := image.NewRGBA(bounds)

	// Fill with white background
	draw.Draw(dst, bounds, &image.Uniform{color.White}, image.Point{}, draw.Src)

	// Composite the image on top
	draw.Draw(dst, bounds, img, bounds.Min, draw.Over)

	return dst
}

x.imagegen.image.readJPEGOrientation.source_code:
func readJPEGOrientation(data []byte) int {
	if len(data) < 2 || data[0] != 0xFF || data[1] != 0xD8 {
		return 1 // Not JPEG
	}

	r := bytes.NewReader(data[2:])
	for {
		var marker [2]byte
		if _, err := r.Read(marker[:]); err != nil || marker[0] != 0xFF {
			return 1
		}

		if marker[1] == 0xE1 { // APP1 (EXIF)
			var lenBytes [2]byte
			if _, err := r.Read(lenBytes[:]); err != nil {
				return 1
			}
			segLen := int(uint16(lenBytes[0])<<8|uint16(lenBytes[1])) - 2
			if segLen < 14 {
				r.Seek(int64(segLen), 1)
				continue
			}
			seg := make([]byte, segLen)
			if _, err := r.Read(seg); err != nil {
				return 1
			}
			if string(seg[:4]) == "Exif" && seg[4] == 0 && seg[5] == 0 {
				return parseTIFFOrientation(seg[6:])
			}
			continue
		}

		if marker[1] == 0xD9 || marker[1] == 0xDA {
			return 1 // EOI or SOS
		}
		if marker[1] >= 0xD0 && marker[1] <= 0xD7 {
			continue // RST markers
		}

		var lenBytes [2]byte
		if _, err := r.Read(lenBytes[:]); err != nil {
			return 1
		}
		segLen := int(uint16(lenBytes[0])<<8|uint16(lenBytes[1])) - 2
		if segLen > 0 {
			r.Seek(int64(segLen), 1)
		}
	}
}

x.imagegen.image.parseTIFFOrientation.source_code:
func parseTIFFOrientation(tiff []byte) int {
	if len(tiff) < 8 {
		return 1
	}

	var big bool
	switch string(tiff[:2]) {
	case "MM":
		big = true
	case "II":
		big = false
	default:
		return 1
	}

	u16 := func(b []byte) uint16 {
		if big {
			return uint16(b[0])<<8 | uint16(b[1])
		}
		return uint16(b[1])<<8 | uint16(b[0])
	}
	u32 := func(b []byte) uint32 {
		if big {
			return uint32(b[0])<<24 | uint32(b[1])<<16 | uint32(b[2])<<8 | uint32(b[3])
		}
		return uint32(b[3])<<24 | uint32(b[2])<<16 | uint32(b[1])<<8 | uint32(b[0])
	}

	if u16(tiff[2:4]) != 42 {
		return 1
	}

	ifdOffset := u32(tiff[4:8])
	if int(ifdOffset)+2 > len(tiff) {
		return 1
	}

	numEntries := u16(tiff[ifdOffset : ifdOffset+2])
	for i := range int(numEntries) {
		offset := ifdOffset + 2 + uint32(i)*12
		if int(offset)+12 > len(tiff) {
			break
		}
		if u16(tiff[offset:offset+2]) == 0x0112 { // Orientation tag
			o := int(u16(tiff[offset+8 : offset+10]))
			if o >= 1 && o <= 8 {
				return o
			}
			return 1
		}
	}
	return 1
}

x.imagegen.image.applyOrientation.source_code:
func applyOrientation(img image.Image, orientation int) image.Image {
	if orientation <= 1 || orientation > 8 {
		return img
	}

	bounds := img.Bounds()
	w, h := bounds.Dx(), bounds.Dy()

	outW, outH := w, h
	if orientation >= 5 {
		outW, outH = h, w
	}

	out := image.NewRGBA(image.Rect(0, 0, outW, outH))
	for y := range h {
		for x := range w {
			var dx, dy int
			switch orientation {
			case 2:
				dx, dy = w-1-x, y
			case 3:
				dx, dy = w-1-x, h-1-y
			case 4:
				dx, dy = x, h-1-y
			case 5:
				dx, dy = y, x
			case 6:
				dx, dy = h-1-y, x
			case 7:
				dx, dy = h-1-y, w-1-x
			case 8:
				dx, dy = y, w-1-x
			}
			out.Set(dx, dy, img.At(x+bounds.Min.X, y+bounds.Min.Y))
		}
	}
	return out
}

