func PrepareTextIDs(seqLen int32) *mlx.Array {
	ids := make([]float32, seqLen*4)
	for i := int32(0); i < seqLen; i++ {
		idx := i * 4
		ids[idx+0] = 0             // T = 0
		ids[idx+1] = 0             // H = 0
		ids[idx+2] = 0             // W = 0
		ids[idx+3] = float32(i)    // L = sequence position
	}
