func CalculateShift(imgSeqLen int32, numSteps int) float32 {
	a1, b1 := float32(8.73809524e-05), float32(1.89833333)
	a2, b2 := float32(0.00016927), float32(0.45666666)

	seqLen := float32(imgSeqLen)

	if imgSeqLen > 4300 {
		return a2*seqLen + b2
	}

	m200 := a2*seqLen + b2
	m10 := a1*seqLen + b1

	a := (m200 - m10) / 190.0
	b := m200 - 200.0*a
	return a*float32(numSteps) + b
}

