func (p *progressTracker) add(n int64) {
	if p == nil || p.callback == nil {
		return
	}
	completed := p.completed.Add(n)
	defer func() {
		if r := recover(); r != nil {
			slog.Debug("progress callback panic (likely closed channel)", "recovered", r)
		}
	}()
	p.callback(completed, p.total)
}

