		endOffset: 3,
		parent:    root,
		lastUsed:  time.Now(),
	}
	root.children = []*trieNode{shared}

	longer := &trieNode{
		tokens:    []int32{10, 11, 12, 13, 14},
		endOffset: 8,
		parent:    shared,
		lastUsed:  time.Now(),
	}
	shorter := &trieNode{
		tokens:    []int32{10, 11, 12},
		endOffset: 6,
		parent:    shared,
		lastUsed:  time.Now(),
	}
	// Put longer first so naive first-match would pick it.
	shared.children = []*trieNode{longer, shorter}

