func prependLibraryPath(dir string) {
	var envVar string
	switch runtime.GOOS {
	case "darwin":
		envVar = "DYLD_LIBRARY_PATH"
	case "linux":
		envVar = "LD_LIBRARY_PATH"
	default:
		return
	}
	if existing := os.Getenv(envVar); existing != "" {
		os.Setenv(envVar, dir+string(filepath.ListSeparator)+existing)
	} else {
		os.Setenv(envVar, dir)
	}
}

