			thinkEnabled: true,
			wantThinking: "I need to consider multiple factors...",
			wantContent:  "",
		},
		{
			name:         "thinking disabled - direct content",
			input:        "Here is my direct answer.",
			thinkEnabled: false,
			wantThinking: "",
			wantContent:  "Here is my direct answer.",
		},
		{
			name:          "thinking with tool call",
