			// Define tools for tool call tests
			props := api.NewToolPropertiesMap()
			props.Set("query", api.ToolProperty{Type: api.PropertyType{"string"}})
			tools := []api.Tool{
				{
					Function: api.ToolFunction{
						Name: "search",
						Parameters: api.ToolFunctionParameters{
							Properties: props,
